const body = $input.first().json.body;

if (!body || typeof body !== "object" ||
    Array.isArray(body)) {
  return [{
    json: {
      status: "invalid_request",
      message: "Expected a JSON object"
    }
  }];
}

const request = {};
const questions = [];

function ask(field, text, type, options = []) {
  questions.push({ field, text, type, options });
}

function choice(label, value) {
  return { label, value };
}

// 1. Location
if (typeof body.location === "string" &&
    body.location.trim()) {
  request.location = body.location.trim();
} else {
  ask("location", "Where is care needed?", "single_select", [
    choice("Petaling Jaya", "Petaling Jaya"),
    choice("Subang Jaya", "Subang Jaya"),
    choice("Kuala Lumpur", "Kuala Lumpur"),
    choice("Shah Alam", "Shah Alam")
  ]);
}

// 2. Required services
if (Array.isArray(body.required_services) &&
    body.required_services.length > 0 &&
    body.required_services.every(
      s => typeof s === "string" && s.trim()
    )) {
  request.required_services =
    body.required_services.map(s => s.trim().toLowerCase());
} else {
  ask(
    "required_services",
    "What kind of assistance is needed?",
    "multi_select",
    [
      choice("Elderly care", "elderly_care"),
      choice("Mobility assistance", "mobility_assistance"),
      choice("Companionship", "companionship"),
      choice("Dementia care", "dementia_care")
    ]
  );
}

// 3. Date
const isValidDate = value => {
  if (typeof value !== "string" ||
      !/^\d{4}-\d{2}-\d{2}$/.test(value)) {
    return false;
  }
  const date = new Date(`${value}T00:00:00Z`);
  return !Number.isNaN(date.getTime()) &&
    date.toISOString().slice(0, 10) === value;
};

if (isValidDate(body.date)) {
  request.date = body.date;
} else {
  ask("date", "Which date do you need care?", "date");
}

// 4. Start time
if (typeof body.start_time === "string" &&
    /^([01]\d|2[0-3]):[0-5]\d$/.test(body.start_time)) {
  request.start_time = body.start_time;
} else {
  ask("start_time", "When should care begin?", "single_select", [
    choice("Morning (09:00)", "09:00"),
    choice("Afternoon (13:00)", "13:00"),
    choice("Evening (18:00)", "18:00")
  ]);
}

// 5. Duration
if (typeof body.duration_hours === "number" &&
    Number.isFinite(body.duration_hours) &&
    body.duration_hours > 0) {
  request.duration_hours = body.duration_hours;
} else {
  ask("duration_hours", "How long is care needed?", "single_select", [
    choice("2 hours", 2),
    choice("4 hours", 4),
    choice("6 hours", 6),
    choice("8 hours", 8)
  ]);
}

// 6. Budget
if (typeof body.max_budget === "number" &&
    Number.isFinite(body.max_budget) &&
    body.max_budget > 0) {
  request.max_budget = body.max_budget;
} else {
  ask("max_budget", "What is your total budget?", "single_select", [
    choice("RM100", 100),
    choice("RM150", 150),
    choice("RM200", 200),
    choice("RM300", 300)
  ]);
}

// Preferred language is optional.
request.preferred_language =
  typeof body.preferred_language === "string"
    ? body.preferred_language.trim()
    : "";

// Ask about missing details, one at a time.
if (questions.length > 0) {
  return [{
    json: {
      status: "needs_clarification",
      draft_request: request,
      question: questions[0],
      missing_fields: questions.map(q => q.field)
    }
  }];
}

// This prototype supports same-day care only.
const [hours, minutes] =
  request.start_time.split(":").map(Number);

const endMinutes =
  hours * 60 + minutes + request.duration_hours * 60;

if (endMinutes > 1440) {
  delete request.start_time;

  return [{
    json: {
      status: "needs_clarification",
      draft_request: request,
      question: {
        field: "start_time",
        text: "This demo supports same-day care. Please choose an earlier start time or adjust the duration.",
        type: "time",
        options: []
      },
      missing_fields: ["start_time"]
    }
  }];
}

// Ask for confirmation before searching.
if (body.confirmed !== true) {
  return [{
    json: {
      status: "needs_confirmation",
      message: "Are these care requirements correct?",
      draft_request: request,
      options: [
        choice("Confirm & Search", true),
        choice("Change Details", false)
      ]
    }
  }];
}

// All details collected and confirmed.
return [{
  json: {
    status: "valid",
    request
  }
}];

const data = $input.first().json;

if (data.status === "invalid_request") {
  return [{ json: data }];
}

const request = data.request;
const providers = data.providers;

function toMinutes(time) {
  const [hours, minutes] = time.split(":").map(Number);
  return hours * 60 + minutes;
}

const requestedStart = toMinutes(request.start_time);
const requestedEnd =
  requestedStart + request.duration_hours * 60;

function isAvailable(provider) {
  return provider.availability.some(slot => {
    return (
      slot.date === request.date &&
      toMinutes(slot.start) <= requestedStart &&
      toMinutes(slot.end) >= requestedEnd
    );
  });
}

function totalCost(provider) {
  return provider.hourly_rate * request.duration_hours;
}

const eligible = providers.filter(provider => {
  const locationMatch =
    provider.location.toLowerCase() ===
    request.location.toLowerCase();

  const servicesMatch =
    request.required_services.every(service =>
      provider.services.includes(service)
    );

  const verifiedMatch = provider.verified === true;
  const availabilityMatch = isAvailable(provider);

  const budgetMatch =
    totalCost(provider) <= request.max_budget;

  return (
    locationMatch &&
    servicesMatch &&
    verifiedMatch &&
    availabilityMatch &&
    budgetMatch
  );
});

const ranked = eligible.map(provider => {
  const cost = totalCost(provider);

  const ratingScore = (provider.rating / 5) * 100;

  const affordabilityScore =
    (1 - cost / request.max_budget) * 100;

  const languageMatch =
    !request.preferred_language ||
    provider.languages.some(language =>
      language.toLowerCase() ===
      request.preferred_language.toLowerCase()
    );

  // If language is not specified, assign neutral score.
  const languageScore =
    !request.preferred_language ? 50 :
    languageMatch ? 100 : 0;

  const score =
    ratingScore * 0.50 +
    affordabilityScore * 0.35 +
    languageScore * 0.15;

  return {
    provider_id: provider.provider_id,
    name: provider.name,
    location: provider.location,
    hourly_rate: provider.hourly_rate,
    estimated_cost: cost,
    currency: "MYR",
    rating: provider.rating,
    verified: provider.verified,
    languages: provider.languages,
    preferred_language_match: languageMatch,
    available: true,
    match_score: Number(score.toFixed(2))
  };
});

ranked.sort((a, b) =>
  b.match_score - a.match_score ||
  a.estimated_cost - b.estimated_cost ||
  a.provider_id.localeCompare(b.provider_id)
);

return [{
  json: {
    status: ranked.length > 0
      ? "matches_found"
      : "no_matches",
    request,
    total_matches: ranked.length,
    matches: ranked.slice(0, 5),
    data_source: "fictional_demo",
    booking_status: "not_booked"
  }
}];

const request = $('Validate Input').first().json.request;

function splitValues(value) {
  return String(value ?? '')
    .split('|')
    .map(s => s.trim())
    .filter(Boolean);
}

// Convert UTC timestamps into Malaysia calendar dates.
function normalizeDate(value) {
  if (!value) return '';

  const text = String(value);

  // Already in YYYY-MM-DD format.
  if (/^\d{4}-\d{2}-\d{2}$/.test(text)) {
    return text;
  }

  const date = new Date(text);
  if (Number.isNaN(date.getTime())) {
    return '';
  }

  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: 'Asia/Kuala_Lumpur',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  }).formatToParts(date);

  const fields = Object.fromEntries(
    parts.map(part => [part.type, part.value])
  );

  return `${fields.year}-${fields.month}-${fields.day}`;
}

const providers = $input.all()
  .map(item => item.json)
  .filter(row => row.provider_id)
  .map(row => ({
    provider_id: String(row.provider_id),
    name: String(row.name ?? ''),
    location: String(row.location ?? ''),
    hourly_rate: Number(row.hourly_rate),
    rating: Number(row.rating),
    verified: row.verified === true ||
      String(row.verified).toLowerCase() === 'true',
    services: splitValues(row.services)
      .map(s => s.toLowerCase()),
    languages: splitValues(row.languages),
    availability: [{
      date: normalizeDate(row.available_date),
      start: String(row.available_from ?? ''),
      end: String(row.available_to ?? '')
    }]
  }));

return [{
  json: {
    status: 'valid',
    request,
    providers
  }
}];

const data = $input.first().json;
const request = data.request;
const providers = data.providers || [];

function toMinutes(time) {
  if (typeof time !== "string") return NaN;
  const [h, m] = time.split(":").map(Number);
  return h * 60 + m;
}

const start = toMinutes(request.start_time);
const end = start + request.duration_hours * 60;

const diagnostics = providers.map(provider => {
  const checks = {
    location:
      provider.location.toLowerCase() ===
      request.location.toLowerCase(),

    services:
      request.required_services.every(service =>
        provider.services.includes(service)
      ),

    verified:
      provider.verified === true,

    availability:
      provider.availability.some(slot =>
        slot.date === request.date &&
        toMinutes(slot.start) <= start &&
        toMinutes(slot.end) >= end
      ),

    budget:
      provider.hourly_rate *
      request.duration_hours <= request.max_budget
  };

  return {
    provider_id: provider.provider_id,
    name: provider.name,
    eligible: Object.values(checks).every(Boolean),
    checks,
    failed_checks: Object.keys(checks).filter(
      key => !checks[key]
    ),
    actual_values: {
      location: provider.location,
      services: provider.services,
      verified: provider.verified,
      availability: provider.availability,
      estimated_cost:
        provider.hourly_rate * request.duration_hours
    }
  };
});

return [{
  json: {
    ...data,
    debug: {
      provider_count: providers.length,
      diagnostics
    }
  }
}];
